"Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim. Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim.": "Rompi tutti i mattoncini senza far cadere la palla. Ha mattoncini resistenti, bonus che cadono e livelli infiniti. Rompi tutti i mattoncini senza far cadere la palla. Ha mattoncini resistenti, bonus che cadono e livelli infiniti.",
"Os teus veículos, localização e garagem. Localiza, favorita, dá alcunhas.": "I tuoi veicoli, la posizione e il garage. Localizza, aggiungi ai preferiti, dai un soprannome.",
"Salas anónimas por alcunha. As mensagens ficam guardadas no servidor. Por alcunha. As mensagens ficam no servidor.": "Stanze anonime con soprannome. I messaggi restano salvati sul server. Con soprannome. I messaggi restano sul server.",
